insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-a-block-is-a-block-sam-2026-11-21','decision','A block is a block: every blocked job goes on Needs you','Sam, 2026-11-21 about 7:04 AM PT, relayed by COBIx on #3358 (comment 7064588752): "a block is a block regardless of whose it is to clear." Every blocked job goes on Needs you, under Collect as Stuck: waiting on a fix, with who clears it and since when, ranked with everything else, Sky''s own blocks included (CCSF''s Cal-GETC dry run). Until the view exists, each handoff lists the blocks.',array['conductor','commons','needs-you','sam-ruling'],'verified','#3358 comment 7064588752','Sam (relayed by COBIx)',now(),'SkyPuffin (S697)',date '2026-11-21'),
('r-vault-notes-merge-on-checks-sam-2026-11-21','decision','Vault-note drafts merge on their own once their checks pass','Sam, 2026-11-21 about 7:04 AM PT, relayed by COBIx on #3358 (comment 7064588752; COBIx''s wording): vault-note drafts in samueltlee/CPLBrain merge on their own once their checks pass, under the Nov 18 rule that yes-style goes are Sky''s. A vault note goes to Sam only when it changes or adds one of his rulings, said in one line; the morning brief stops listing routine vault merges as his decisions.',array['vault','checkpoint','merge','sam-ruling'],'verified','#3358 comment 7064588752','Sam (relayed by COBIx)',now(),'SkyPuffin (S697)',date '2026-11-21'),
('d-orange-coast-main-run-stands-s697','decision','Orange Coast''s live rows take main''s run 39726645292','S697 conductor: Orange Coast''s 109 live rows at run 38670927724 gave way to main''s 39726645292, which passes or ties on all 109 and is better on 6; the live read before the rereads found no live row better than main''s file and none newer, which settles f-orange-coast-live-rows-older-run-s690. Reread 44909976872 (#3640); its receipt undoes it.',array['program-requirements','orange-coast','reread'],'proposed','#3640','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('d-named-gaps-compact-apply-s697','decision','Both named-gap guarded UPDATEs ran in compact form','S697 conductor: both named-gap guarded UPDATEs (total_not_printed 6 of 6 at 13:37Z, #3640; total_differs 10 of 10 at 16:38Z, #3649) ran in compact form: the same guards on run, before checks and no person''s check, with the result equal to each plan''s after_checks, so each plan''s rollback applies unchanged. #3640''s receipt says so in its applied field.',array['program-requirements','named-gaps','rule-10'],'proposed','#3640; #3649','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('d-cerritos-20504-waits-on-44984-s697','decision','Cerritos 20504 waits on 44984, held for a person','S697 conductor: Cerritos 20504 was left out of the night''s free rereads because its run also holds 44984, a record held for a person. 20504 waits until a person settles 44984, so no reread touches a held record.',array['program-requirements','cerritos','held-for-person'],'proposed','docs/session_698_handoff.md','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('d-load-skips-places-none-s697','decision','Cosumnes River''s load needed no only input','S697 conductor: Cosumnes River''s load 44917693465 ran with no only input, because load_rows skips records that place no courses (28 here); it inserted 7, and the reread 44917690048 replaced 4 live rows (189 live, 10 passing at the new run). #3645.',array['program-requirements','cosumnes-river','load'],'proposed','#3645','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('d-outline-load-strips-letterless-lines-s697','decision','The outline load drops a line with no letter','S697 conductor: the course outline load drops a filed line holding no letter (a bare number), 23 lines and 2 rows statewide (Irvine Valley HLTH 7 and KNES 64), at the load rather than in the parser, so no committed recall gate goes stale. Load 44925768837 (#3642).',array['course-outcomes','irvine-valley','load'],'proposed','#3642; kb/receipts/course_outcomes_saddleback_44925768837.json','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('d-display-held-for-gaps-apply-s697','decision','The display build waited for the named gaps'' apply','S697 conductor: the night''s display build (#3650, 9d9244ee7496) waited until the total_differs guarded UPDATE on program_requirement_records had run (16:38Z), so two writes never ran on one table at once. Santa Monica went first (44925708471, 230 of 230); the gate read at 16:42:55Z moved only Santa Monica''s 230.',array['program-requirements','display','rule-10'],'proposed','#3650','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('d-vault-note-merged-under-ruling-s697','decision','S691''s vault note merged under Sam''s vault-note ruling','S697 conductor: S691''s vault note samueltlee/CPLBrain#837 merged (c9da8405) under Sam''s ruling of 2026-11-21 that vault-note drafts merge on their own once their checks pass (r-vault-notes-merge-on-checks-sam-2026-11-21). It had no checks configured and carried no ruling of his.',array['vault','checkpoint','merge'],'proposed','samueltlee/CPLBrain#837','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('d-ivc-load-receipt-rides-checkpoint-s697','decision','Irvine Valley''s load branch merges through the checkpoint','S697 conductor: Irvine Valley''s load branch claude/s697-ivc-load (its trigger file and receipts) merges through the checkpoint PR #3639, because a head that is only the runner''s receipt commit runs no test (p-bot-receipt-head-runs-no-test-s697).',array['course-outcomes','merge','ci'],'proposed','#3639','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('p-check-generated-misses-commons-data-s697','pitfall','check_generated.sh reads current while the Commons data are stale','S697: after a records change, scripts/check_generated.sh reported current while tests/commons_data_status_build_test.py found kb/status/commons_data.json and the college sidecars stale: check_generated.sh runs neither Commons builder. Run kb/_build_commons_data_status.py under Python 3.12, then its test.',array['ci','generated-files','commons'],'proposed','docs/kb-notes/methodology-chain-prs-when-every-merge-conflicts-a-generated-file.md','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('p-bot-receipt-head-runs-no-test-s697','pitfall','A bot receipt head runs no test','S697: a branch whose head is the runner''s receipt commit (Irvine Valley''s load, claude/s697-ivc-load) starts no test run. Push a real change, such as the receipt''s closing live count, never an empty commit. That push re-ran the load (44926139513: 0 inserted, 1,732 kept), harmless because the load keeps what it finds.',array['ci','receipts','conductor'],'proposed','docs/reference/conductor_mode.md (S697)','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('p-commons-files-conflict-between-prs-s697','procedure','Two records PRs conflict on the Commons files: rebuild, never hand-merge','S697: every records PR rebuilds the Commons files (kb/status/commons.json, commons_data.json and its college sidecars), so two open at once conflict when the first merges. Merge one, merge main into the next, take main''s side of each conflicted Commons file and rerun both builders, kb/_build_commons_status.py and kb/_build_commons_data_status.py, under Python 3.12.',array['ci','generated-files','commons','merge'],'proposed','docs/kb-notes/methodology-chain-prs-when-every-merge-conflicts-a-generated-file.md','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('f-s680-pin-test-pinned-old-pages-s697','fact','The S680 pin test pinned Cosumnes River''s old pages','S697: #3645 failed lints on the S680 test that pinned Cosumnes River''s old catalog pages, once the named-programs read used the pin''s page. The test now expects the pin''s page (3c85e208). A test that pins a college''s pages fails whenever a pin moves them.',array['tests','cosumnes-river','program-requirements'],'proposed','#3645','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('f-total-differs-gap-s697','fact','A named gap for a printed total the printed units do not reach','S697 (#3649): a new named gap, total_differs: the catalog prints a program total its own printed units do not reach. Self-recall 1,843 right, 0 wrong. Applied by a guarded UPDATE, 10 of 10 at 16:38Z (Clovis 33493, 35209, 37352, 42234, 42706, 44551; Glendale 12570, 12574, 19566, 39905); the second reader dropped Clovis 33431 (floors over lists).',array['program-requirements','named-gaps','clovis','glendale'],'proposed','#3649','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('f-followup-four-left-s697','fact','Four reader findings wait for the next night''s follow-up','S697: #3644''s second reader left four findings for the next night''s one follow-up (two rounds reached): a test for the own-run filter in kb/_program_reread_keep_better.py; named_fragment reads any = as viewer parameters; EDITION_TOKEN still joins catalog-v24 and -v25; a capture-only prior read with no PDF page now ends red (College of the Desert''s preview 44711759115).',array['program-requirements','reader','follow-up'],'proposed','#3644','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('f-clovis-19-left-s697','fact','Clovis''s 19 programs left, measured','S697: Clovis has 19 programs left after the total_differs gap. Business 33432, 33433, 33487, 33491 and Social Science 33492 start or are cut at a page break, so each needs a pin and a paid reread; the other 14 read pairs or "any course from List A" wrongly, a reader fix.',array['program-requirements','clovis','cheap-piles'],'proposed','docs/program_requirements_harvest_lessons.md (S697)','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('f-glendale-28-left-s697','fact','Glendale''s 28 programs left, measured','S697: Glendale has 28 left. 11 with no record file need a paid extraction (40846, 40847, 21302, 38973, 24377, 24327, 37070, 36599, 36601, 11155, 21303). Of 17 more, 8 language records take a list "If 20 units have not been reached" (a scorer kind), 18639 prints EIGHTEEN, 32607, 36416 and 12503 read pairs wrongly, and 44488, 45068, 18640 and 30813 fail coverage.',array['program-requirements','glendale','cheap-piles'],'proposed','docs/program_requirements_harvest_lessons.md (S697)','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('m-collection-s697','milestone','S697''s program records: 7 new, 119 replaced, 16 with a named gap','S697: 7 new program records (Cosumnes River), 119 replaced by a better reread (Orange Coast 109, Hartnell 2, Imperial Valley 2, Oxnard 1, Cosumnes River 4, Glendale 1), 20 of them newly passing, and 16 collected with a named gap (6 total_not_printed, 10 total_differs), for $1.16 of extraction. #3640, #3645, #3649.',array['program-requirements','collection','reread'],'proposed','#3640; #3645; #3649','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('m-cosumnes-river-named-read-s697','milestone','Cosumnes River''s named-programs read: 10 of 14 pass','S697 (#3645 c85bb975): the free pricing run 44916368634 named exactly the 14 (would_extract with only); the paid read 44917314201 cost $1.16: 10 pass, 33053 is partial (a page-break pin), and 20147, 20193 and 20227 place none (each needs its own page). Reread 44917690048 replaced 4 live rows; load 44917693465 inserted 7.',array['program-requirements','cosumnes-river','collection'],'proposed','#3645','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('m-ivc-outlines-loaded-s697','milestone','Irvine Valley''s outlines loaded: 1,732 rows','S697 (#3642 0695b665): Irvine Valley''s outlines, read on Saddleback''s curriQunet host: index 44908824732 (1,199 current outlines), trial 44911142170 (12 of 12), full read 44913397609 (868 pages, every one 200). Load 44925768837: 1,732 rows, 864 SLO rows holding 2,639 SLOs and 868 objective rows holding 6,695 objectives, confirmed live at 16:41Z.',array['course-outcomes','irvine-valley','collection'],'proposed','#3642; kb/receipts/course_outcomes_saddleback_44925768837.json','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21'),
('m-reader-fixes-s697','milestone','The reader fixes of S697: short reads, same-page calls, only','S697: #3641 (32b00c99): a short read files nothing (read_short), the same-page calls in one place, the named-programs only input, Butte''s address compare (320 committed records newly unchanged: Butte 163, Cuyamaca 155, College of the Canyons 2). #3644 (25a8917a): a killed wave extraction and a timed-out prior read file nothing, named_fragment(), EDITION_TOKEN, kept entries under only=.',array['program-requirements','reader','reread'],'proposed','#3641; #3644','SkyPuffin (S697), the conductor',null,'SkyPuffin (S697)',date '2026-11-21')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
